  "heroglyph.flow.ownerFinal.infoBody": "HEROGLYPH दो फ्रेमों से मिलकर बनता है, जो साथ मिलकर आपके कुत्ते की असली पहचान बनाते हैं। प्राचीन मिस्र में देवताओं और फ़राओं के नाम ऐसे ही सुरक्षात्मक अंडाकार फ्रेमों — कार्टूश — में लिखे जाते थे, ताकि उनकी विरासत अनंत काल तक बनी रहे।",
