  "heroglyph.flow.dogCharacter.slide.chiller.title": "आरामपसंद (सोफ़ा)",
  "heroglyph.flow.dogCharacter.slide.guardian.desc": "दरवाज़े की ऐसे रखवाली करता है जैसे वह परलोक का द्वार हो। पहले भौंकता है, सवाल कभी नहीं पूछता।",
  "heroglyph.flow.dogCharacter.slide.player.desc": "गेंद के एक और थ्रो के लिए अपनी आत्मा तक दे देगा। सबसे बड़ी ख़ुशी: पसंदीदा खिलौना।",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "कोई ऑफ़ बटन नहीं। बैटरी की ज़रूरत नहीं। सबसे आम सवाल: इस कुत्ते ने क्या खा रखा है?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "आज के ज़माने का समुद्री डाकू — अपनी दुनिया, अपने नियम। चुनिंदा सुनना उसका पहला क़ानून है।",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "कुत्ते दो तरह के होते हैं — और एक को मछली समझने की भूल हो सकती है। गीला फ़र: 100% ख़ुशी।",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "खाना ही मिशन है। पूरी लगन, ज़रा भी हिचक नहीं — और आपकी थाली में बचा सब कुछ भी खा जाएगा।",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "उसके लिए कोई अजनबी नहीं। डाकिये से ऐसे मिलता है जैसे बरसों से बिछड़ा हमदम हो। हर बार।",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "कुछ भी न करने की प्राचीन कला में माहिर — और वह भी पूरी शान से।",
