  "heroglyph.flow.reveal.visionTribute": "आपके प्रतीकात्मक योगदान के लिए धन्यवाद। जब हम बहुत हों, तो थोड़ा भी काफ़ी है — और आपकी वजह से दुनिया थोड़ी बेहतर हो गई।",
