  "notFound.code": "404",
  "notFound.message": "ओह! पृष्ठ नहीं मिला",
  "notFound.returnHome": "मुखपृष्ठ पर वापस जाएं",
  "about.origin.title": "मूल<br />कहानी",
  "about.origin.sub": "स्लाइड करें और पढ़ें",
  "about.origin.skip": "या छोड़ें",
  "about.crawl.intro": "दस साल पहले, यूरोप के हृदय में एक आश्रय में….",
  "about.crawl.episode": "अध्याय I",
  "about.crawl.faith": "एक नई आस्था",
  "about.crawl.p1": "2016 में, आठ काले पिल्ले एक ही डिब्बे में फेंके गए — आश्रय में आए। सात को घर मिल गया। सबसे बड़े को कोई नहीं चाहता था — वह पूरे एक साल इंतज़ार करता रहा। उसका नाम था Hekthor।",
  "about.crawl.p2": "एक दिन एक जोड़ा Sindy को देखने आश्रय आया, एक छोटी सफेद मादा जिसे वे गोद लेना चाहते थे। महज संयोग से, Hekthor उस समय उसके बाड़े में था — उसका अपना बाड़ा तब साफ हो रहा था। वह पुरुष, जो केवल साथ आया था और कभी कुत्ता नहीं चाहता था, उस काले कुत्ते से पहली ही नज़र में प्यार कर बैठा।",
  "about.crawl.p3": "एक हफ्ते बाद दोनों साथ थे, और एक खूबसूरत कहानी शुरू हुई। उस पुरुष का पूरा जीवन बदल गया, और समय के साथ उसे एक बात समझ आई: केवल वही व्यक्ति जरूरतमंद कुत्तों की सच्ची मदद कर सकता है जिसके पास कुत्ता हो और जो जानता हो कि कुत्ते का प्यार कैसा होता है।",
  "about.crawl.p4": "और इस तरह Heroglyph का जन्म हुआ — एक प्रतीक जो हर जगह के कुत्ता प्रेमियों को दुनिया के सबसे बड़े समुदाय में एकजुट करने के लिए बना था। एक समुदाय जो हमारे लिए, हमारे कुत्तों के लिए, और आने वाली पीढ़ियों के लिए खड़ा होगा — उन लोगों के लिए जो यह मानने से नहीं डरते कि कुत्ता केवल एक जानवर नहीं, बल्कि एक ऐसा प्राणी है जो हमें बेहतर इंसान बनाता है।",
  "about.crawl.p5": "अभी, पहले पड़ाव की यात्रा शुरू होती है — 1,000,000 Heroglyph बनाने की। और आप इसका हिस्सा बन सकते हैं। क्योंकि जो लोग यह मानने के लिए काफी पागल हैं कि वे दुनिया बदल सकते हैं, वही ऐसा करते हैं।",
  "about.crawl.p6": "हम कुत्ते में विश्वास करते हैं।",
  "about.timeline.heading": "DOGYPT की कहानी",
  "about.milestone.1.year": "2017",
  "about.milestone.1.tag": "आश्रय",
  "about.milestone.1.title": "आश्रय में खज़ाना",
  "about.milestone.1.body": "एक काला कुत्ता जिसे कोई नहीं चाहता था, आश्रय की बाड़ के पीछे इंतज़ार कर रहा था। उसका नाम Hekthor बना। उसे गोद लेना बचाव नहीं था — यह सब कुछ की शुरुआत थी।",
  "about.milestone.2.year": "2018",
  "about.milestone.2.tag": "बंधन",
  "about.milestone.2.title": "शाश्वत बंधन",
  "about.milestone.2.body": "उसने बिना एक शब्द कहे मुझे जीवन के सबसे कठिन दौर से निकाला। हर कुत्ता प्रेमी यह जानता है — वे ठीक तब आपको उठाते हैं जब आप गिर रहे होते हैं।",
  "about.milestone.3.year": "2019",
  "about.milestone.3.tag": "यात्रा",
  "about.milestone.3.title": "वह सफर जो किताब बन गया",
  "about.milestone.3.body": "हम साथ मिलकर Slovakia पार किए — 42 दिन, 800 किलोमीटर, एक शांत वादा। वह रास्ता एक किताब बन गया: „Cesta s Hrdinom\" — एक नायक के साथ सफर।",
  "about.milestone.4.year": "2022",
  "about.milestone.4.tag": "नाम",
  "about.milestone.4.title": "कुत्ता प्रेमियों का राष्ट्र",
  "about.milestone.4.body": "पिरामिड, रहस्यवाद, मिस्र की शाश्वत महिमा — मानवता सहस्राब्दियों से मंत्रमुग्ध रही है। इसे कुत्ते के अनंत प्रेम से जोड़ें और आपको मिलता है DOGYPT। मैंने यह विचार Expo Dubai 2022 में एक फराओ के रूप में सील किया।",
  "about.milestone.5.year": "अभी",
  "about.milestone.5.tag": "Dogypt",
  "about.milestone.5.title": "यात्रा आपसे शुरू होती है",
  "about.milestone.5.body": "DOGYPT उन सभी के लिए एक आंदोलन है जिनका जीवन एक कुत्ते ने बदल दिया। पृथ्वी के सबसे पुराने, सबसे ईमानदार बंधन पर बना। Hekthor संस्थापक #1 है। आप अगले हैं।",
  "about.outro.quoteLead": "यह कभी नहीं था",
  "about.outro.quoteTail": "\"बस एक कुत्ता।\"",
  "about.outro.body": "आप पहले से ही यह अहसास जानते हैं — कि कुत्ता कोई चीज़ नहीं जिसे आप रखते हैं, बल्कि <strong>कोई है जिससे आप प्यार करते हैं</strong>। अब कल्पना करें वह प्यार संगठित, जुड़ा हुआ, <strong>इतना शक्तिशाली कि चीज़ें बदल सके।</strong> और इसीलिए <strong>DOGYPT</strong> अस्तित्व में है।",
  "about.outro.name1": "Matej",
  "about.outro.and": "और",
  "about.outro.name2": "Hekthor",
  "about.outro.cta": "डॉगिप्तवासी बनें",
  "about.reel.prev": "पिछली फ़ोटो",
  "about.reel.next": "अगली फ़ोटो",
