  "religion.aria.preamble": "प्रस्तावना",
  "religion.aria.sacredIndex": "पवित्र सूचकांक",
  "religion.aria.scrollDown": "नीचे स्क्रॉल करें",
  "religion.preamble.headlineGrad": "कुत्ते पर",
  "religion.preamble.headlineLine": "हम भरोसा करते हैं",
  "religion.preamble.text": "हम, कुत्ता प्रेमियों का राष्ट्र — पृथ्वी पर हर कुत्ते की <strong>अनंत वफ़ादारी</strong>, <strong>सच्चे प्यार</strong> और <strong>शुद्ध आत्मा</strong> को जानते हुए — मानव समाज में कुत्तों की स्थिति ऊंची करने, उनके लिए एक <strong>समुदाय</strong> बनाने, उनके जीवन को <strong>बेहतर</strong> करने, और जरूरतमंद हर कुत्ते के भाग्य को <strong>फिर से लिखने</strong> के लिए, खुद को यह संविधान देते हैं।",
  "religion.preamble.oath": "झुंड की शपथ",
  "religion.bookTitle": "कुत्ता प्रेमियों की \"बाइबिल\"",
  "religion.book.sealAlt": "डॉगिप्तवासी मुहर",
  "religion.book.titleThe": "The",
  "religion.book.titleBrand": "Dogypt",
  "religion.book.titleConstitution": "संविधान",
  "religion.book.trust": "कुत्ते पर हम भरोसा करते हैं",
  "religion.book.sub": "हर कुत्ता प्रेमी के लिए अनिवार्य पाठ जो डॉगिप्तवासी बनना चाहता है।",
  "religion.book.cta1.kicker": "मार्ग शुरू होता है",
  "religion.book.cta1.head": "धर्म से<br />जुड़ें",
  "religion.book.cta1.text": "कुत्ते के धर्म के लिए साइन अप करें — एक Heroglyph लें।",
  "religion.book.cta1.btn": "डॉगिप्तवासी बनें",
