  "wall.hero.taglineLead": "वह जगह जहाँ",
  "wall.hero.taglineGod": "कुत्ता भगवान है।",
  "wall.hero.cta": "डॉगिप्तवासी बनें",
  "wall.hero.total": "1,000,000",
  "wall.hero.dogs": "कुत्ते",
  "wall.hektor.msg": "Hekthor, तुम मेरे सबसे बड़े नायक हो, मेरे सबसे अच्छे दोस्त, मेरे वफ़ादार साथी, मेरे निर्मम गुरु — तुम मेरी ज़िंदगी की सबसे ख़ूबसूरत कहानी हो। तुम्हारी वजह से मैंने कुत्तों का एक धर्म शुरू किया, और मैंने जाना कि मेरे प्यार में कुछ भी ख़ास नहीं है — जिसने भी कभी किसी कुत्ते से प्यार किया है, वह अपने दिल में बिल्कुल यही महसूस करता है। हमारे साथ बिताए सबसे अच्छे जीवन के लिए धन्यवाद। मैं तुमसे प्यार करता हूँ।",
  "wall.info.title": "1,000,000 कुत्ते।<br/>क्या हम कर पाएंगे?",
  "wall.info.body": "DOGYPT कुत्ता प्रेमियों के लिए एक आंदोलन है। हर कुत्ते को एक अनूठा Heroglyph मिलता है — वैश्विक झुंड में उनकी स्थायी जगह। हम दस लाख नायकों को जमा कर रहे हैं। पहलों में शामिल हों।",
  "wall.filter.find": "नंबर से कुत्ता खोजें",
  "wall.filter.center": "ग्रिड केंद्रित करें",
  "wall.filter.placeholder": "कुत्ता #",
