  "whatNext.s1.title": "पहला कदम",
  "whatNext.s1.hook": "इंसान के लिए एक छोटा कदम — कुत्तों की दुनिया के लिए एक विशाल छलांग।",
  "whatNext.s1.body": "तुम्हारे Heroglyph ने अभी घोषित किया है कि तुम एक ऐसे आंदोलन का हिस्सा हो जो दुनिया भर के कुत्तों का सम्मान करता है। <b>पहला कदम पूरा हो चुका है।</b>",
  "whatNext.s2.title": "अब तुम डॉगिप्तवासी हो",
  "whatNext.s2.hook": "तुम सिर्फ़ एक कुत्ता प्रेमी नहीं — तुम एक पट्टे वाले श्रद्धालु हो।",
  "whatNext.s2.body": "WALL में हमेशा के लिए दर्ज। हम में से हर कोई थोड़ा देता है — और <b>साथ मिलकर, हम कुत्तों को पर्याप्त देते हैं।</b>",
  "whatNext.s3.title": "बदलाव का हिस्सा बनो",
  "whatNext.s3.hook": "एक पंजा एक निशान छोड़ता है। दस लाख एक रास्ता छोड़ते हैं।",
  "whatNext.s3.body": "दस लाख Heroglyphs तक पहुँचने में हमारी मदद करो — अपने दोस्तों को जुड़ने के लिए आमंत्रित करो। <b>ज़्यादा Heroglyphs = हर कुत्ते के लिए ज़्यादा भलाई।</b>",
  "whatNext.s4.title": "संपर्क में रहो",
  "whatNext.s4.hook": "दरवाज़ा खुला है। झुंड इंतज़ार कर रहा है।",
  "whatNext.s4.body": "अपना ईमेल जाँचो और अपनी प्रोफ़ाइल में साइन इन करो — वहीं हम संपर्क में रहेंगे। <b>हमारे कुत्तों के लिए एक जीवन भर चलने वाला ऐप जल्द आ रहा है।</b>",
  "whatNext.greet": "स्वागत है, {name}",
  "whatNext.s4.cta": "कुत्ता तुम्हारे साथ रहे",
