  "heroglyph.sales.transparency.footer": "Setiap euro tetap terbuka, untuk dilihat setiap anggota. Anda tidak membayar sebuah perusahaan — Anda memberi makan sang kawanan.",
  "entry.declare.eyebrow": "Dengan ini saya menyatakan",
  "entry.title": "Kepada Anjing Aku Percaya",
  "entry.subtitle": "Ini bukan lelucon. Setiap agama yang serius harus menyatakan hal-hal ini.",
  "entry.criteria.theology.title": "Teologi",
  "entry.criteria.theology.body": "Sahabat terbaik, penjaga, guru, mitra dalam setiap petualangan. Anjing memberikan cinta tanpa syarat — dan berjalan di sisinya membuat kita lebih manusiawi.",
  "entry.criteria.canon.title": "Kanon",
  "entry.criteria.canon.body": "Setiap kepercayaan memiliki kitab suci. Milik kami adalah DOGMA: ikatan kita dengan anjing yang tertulis dalam dua belas bab, bebas dibaca di dogma.dogypt.com.",
  "entry.criteria.community.title": "Komunitas",
  "entry.criteria.community.body": "Kami adalah pecinta anjing dengan sebuah tujuan. Sendirian, kita masing-masing hanya bisa mengubah sedikit — bersama, kekuatan kita tak terbatas.",
  "entry.criteria.symbol.title": "Simbol",
  "entry.criteria.symbol.body": "Setiap kepercayaan memiliki tandanya. Milik kami adalah heroglyph: tanda suci yang unik untuk setiap anjing, dipahami dalam bahasa apa pun, di mana pun.",
  "entry.criteria.ritual.title": "Ritual",
  "entry.criteria.ritual.body": "Berjalan-jalan. Terapi harian yang menjaga tubuh dan pikiran tetap bugar — dan jiwa pula. Ritual tertua yang sudah kita jalankan tanpa diperintah.",
  "entry.criteria.vision.title": "Visi",
  "entry.criteria.vision.body": "Mengangkat ikatan antara manusia dan anjing — dan memperjuangkan penghormatan serta kehidupan yang lebih baik yang layak diterima setiap anjing.",
  "entry.criteria.offerings.title": "Persembahan",
  "entry.criteria.offerings.note": "(sebuah penghormatan simbolis)",
  "entry.criteria.offerings.pill": "€11 · sekali bayar",
  "entry.criteria.offerings.tag": "100% transparansi",
  "entry.criteria.offerings.body": "€11, sekali saja. Persembahan simbolis — setiap pemasukan dan setiap pengeluaran tercatat dalam buku besar yang terbuka untuk semua. Energi yang membuat kami tetap hidup.",
  "entry.criteria.legitimacy.title": "Legitimasi",
  "entry.criteria.legitimacy.pill": "tersisa {count} anggota",
  "entry.criteria.legitimacy.body": "Seribu pendiri, dan kami cukup kuat untuk mendaftar sebagai sebuah bangsa yang harus diakui hukum. Tanda terakhir — hanya Anda yang bisa mencapainya.",
