  "heroglyph.flow.email.reasonMany": "DOGYPT में हर कुत्ते का अपना एक प्रतीक होता है — HEROGLYPH। इन्हें बनाने में आपका थोड़ा ध्यान लगेगा। अपना ई-मेल दे दें, ताकि बीच में कोई रुकावट आए तो डिज़ाइन खो न जाएँ।",
