  "heroglyph.flow.more.ainubis.d": "हमारा पर्सनलाइज़्ड AI — आपका सहायक और मार्गदर्शक। यह आपके कुत्ते को अंदर-बाहर से जानता है। इसके स्रोतों से सीखें, उनमें झाँकें और अपनी सामग्री व अनुभव जोड़ें।",
  "heroglyph.flow.more.ainubis.t": "AINUBIS",
  "heroglyph.flow.more.cause.d": "DOGYPT कुत्ता प्रेमियों की ज़िंदगी आसान बनाता है, लेकिन साथ ही अच्छे लोगों को जोड़ता है और पारदर्शी तरीक़े से ज़रूरतमंद कुत्तों की मदद करता है। DOGYPT का संस्थापक HEKTHOR भी एक आश्रय से ही आया है।",
