  "heroglyph.flow.more.close": "बंद करें",
  "heroglyph.flow.more.dogid.d": "आपके कुत्ते की पूरी प्रोफ़ाइल एक जगह। आप जो भी भरेंगे, हमारा AINUBIS उसे काम में लाएगा। एक काम का “रिपोर्ट कार्ड” हमेशा हाथ में — जैसे पशु-चिकित्सक के पास।",
  "heroglyph.flow.more.dogid.t": "DOG ID",
  "heroglyph.flow.more.dogtrip.d": "दुनिया भर के dog friendly रोमांच एक जगह। अपनी पसंदीदा सैर जोड़ें और झुंड के साथ साझा करें। दूसरों से प्रेरणा लें, पॉइंट्स, बैज और लेवल जमा करें।",
  "heroglyph.flow.more.dogtrip.t": "DOGTRIP",
  "heroglyph.flow.more.eyebrow": "DOGYPT सदस्यता",
  "heroglyph.flow.more.glyph.d": "एक अनूठा प्रतीक जो आपके कुत्ते को बिल्कुल सटीक दर्शाता है। एक सार्वभौमिक भाषा, जो कुत्ता प्रेमियों को एकजुट करने के लिए बनी है। DOGYPT की आपकी चाबी।",
  "heroglyph.flow.more.glyph.t": "HEROGLYPH",
  "heroglyph.flow.more.money.d": "हर €11 में से €5 विकास पर, €3 समुदाय को, €2 कुत्तों को बचाने पर और €1 Hekthor के कटोरे में जाता है। हर खर्च का हिसाब दर्ज होगा और सार्वजनिक होगा।",
  "heroglyph.flow.more.money.t": "पैसा कहाँ जाता है",
  "heroglyph.flow.more.next": "आगे",
  "heroglyph.flow.more.pack.d": "कुत्ता प्रेमियों के लिए बने प्लेटफ़ॉर्म तक पहुँच। ऐप लगातार बढ़ता रहेगा और हर दिशा में कुत्ता प्रेमियों के काम आएगा।",
  "heroglyph.flow.more.pack.t": "सदस्य अनुभाग",
  "heroglyph.flow.more.prev": "पिछला",
  "heroglyph.flow.more.sniffer.d": "सैर, रोज़ की वॉक या रोड ट्रिप के रोमांच के लिए कोई साथी, जोड़ी या ग्रुप ढूँढें। ख़ास तौर पर कुत्तों और उनके इंसानों के लिए बना मैचमेकर।",
  "heroglyph.flow.more.sniffer.t": "SNIFFER",
  "pack.buddy.intro": "दुनिया को साथ मिलकर सूँघने के लिए साथी ढूँढें।",
