  "heroglyph.flow.stay.done.guest": "AINUBIS फ़ोटो देखेगा, और कुछ ही मिनटों में आपका कुत्ता दीवार पर होगा। आपका heroglyph हम संभालकर रखेंगे — आप कभी भी जुड़ सकते हैं।",
