  "heroglyph.flow.why.head2": "Heroglyph इसे अंकित करता है।",
  "heroglyph.flow.why.leadStrong": "मिलिए ALBA से:",
  "heroglyph.flow.why.leadRest": "एक जैसा नाम, पर बिल्कुल अलग कुत्ते।",
  "heroglyph.flow.why.albNote": "नाम के विपरीत, हर ALBA का अपना अनूठा heroglyph होता है!",
  "heroglyph.flow.why.cta": "Heroglyph बनाएं",
  "heroglyph.flow.why.link": "heroglyph क्यों, और यह किस लिए है?",
  "heroglyph.flow.why.egyptTitle": "शाश्वत विरासत",
  "heroglyph.flow.why.egyptP1": "प्राचीन मिस्र में, शासकों के नाम एक अंडाकार फ्रेम — एक कार्टूश — के भीतर लिखे जाते थे। इसका उद्देश्य उन्हें शाश्वत सुरक्षा देना था।",
  "heroglyph.flow.why.egyptP2": "heroglyph आपके कुत्ते के लिए वही करता है। बारह चिह्न — सात उसके बारे में, पांच आपके बारे में। वह क्या कहलाता है, यह नहीं — बल्कि वह कौन है।",
  "heroglyph.flow.why.egyptP3": "यह प्रतीक DOGYPT की आपकी कुंजी भी है, जहां हर कुत्ता अनूठा है!",
