  "pack.cal.closeHint": "ब्लॉक के बाहर क्लिक करें या Esc दबाएं",
  "pack.cal.life.noBirth": "जीवन अक्ष को जन्म तारीख़ चाहिए। कुत्ते के DOG ID में इसे जोड़ें और ग्रिड पहले सप्ताह से बनेगी।",
  "pack.cal.life.srcNone": "औसत जीवन प्रत्याशा: अभी नस्ल या वज़न नहीं पता, तो अनुमान मध्यम आकार वर्ग पर आधारित है। DOG ID में नस्ल जोड़ें।",
  "pack.cal.life.srcPre": "औसत जीवन प्रत्याशा:",
