  "pack.cal.life.srcBreed": "प्रकाशित नस्ल आंकड़ा",
  "pack.cal.life.srcWeight": "वज़न पर आधारित अनुमान",
  "pack.cal.life.bandNote": "यह हज़ारों कुत्तों का औसत है, इस एक के बारे में कोई भविष्यवाणी नहीं।",
  "pack.cal.life.srcRefBreed": "स्रोत: एक नस्ल क्लब द्वारा प्रकाशित रेंज (AKC / The Kennel Club)।",
  "pack.cal.life.srcRefWeight": "स्रोत: वज़न के अनुसार पशु चिकित्सा जीवन प्रत्याशा सर्वे (UK VetCompass / RVC life tables)।",
  "pack.cal.life.tgtPre": "लक्ष्य:",
  "pack.cal.life.tgtBody": "समग्र देखभाल जो पांच अतिरिक्त साल तक जोड़ सकती है — पतला रहना, ऑफ़-रोड हलचल, दांत, नींद, और जितना हो सके कम अनावश्यक रसायन।",
  "pack.cal.life.tgtSrc": "एक मोटा अनुमान, वादा नहीं। इसमें से सिर्फ़ एक चीज़ मापी गई है: सिर्फ़ पतला रहने से लैब्राडोर को 1.8 साल ज़्यादा मिले (Purina Life Span Study, JAVMA 2002)।",
  "pack.cal.life.intro": "नीचे आपके कुत्ते की पूरी ज़िंदगी ब्लॉक्स में है। एक ब्लॉक = एक सप्ताह, एक पंक्ति = एक साल। एक तरफ़ यह बेचैन करने वाला है, दूसरी तरफ़ यही याद दिलाता है कि हर पल का भरपूर इस्तेमाल करें और चीज़ों को टालें नहीं।",
  "pack.cal.life.fromBirth": "जन्म से गिना गया",
  "pack.cal.life.daysLived": "सबसे अच्छी ज़िंदगी के दिन",
  "pack.cal.life.days": "सबसे अच्छी ज़िंदगी के दिन",
  "pack.cal.life.fromSince": "इससे गिना गया",
  "pack.cal.life.together": "साथ के दिन",
  "pack.cal.life.bestLife": "सबसे अच्छी ज़िंदगी जी।",
  "pack.cal.life.zone": "इतिहास में बहुत कम कुत्ते यहां तक पहुंचे",
  "pack.cal.life.recTitle": "कुत्तों की दीर्घायु कोई संयोग नहीं है",
  "pack.cal.life.recSub": "नीचे कुछ रिकॉर्ड धारक हैं जो लगभग 30 साल तक जीए। एक लंबी, ख़ुशहाल ज़िंदगी ज़्यादातर आपके रोज़ के फ़ैसलों पर टिकी होती है।",
  "pack.cal.life.recPrev": "पिछला",
  "pack.cal.life.recNext": "अगला",
  "pack.cal.life.unverified": "असत्यापित — सिर्फ़ मालिक के कहने पर आधारित",
  "pack.cal.life.tipsTitle": "आप इसके लिए क्या कर सकते हैं",
  "pack.cal.life.tipsSub": "छह चीज़ें जो नस्ल से ज़्यादा मायने रखती हैं। इनमें से किसी में पैसा नहीं लगता, सबमें ध्यान लगता है।",
  "pack.cal.life.protoTitle": "लॉन्गेविटी प्रोटोकॉल",
  "pack.cal.life.protoBody": "वह पूरी प्रक्रिया जिस पर ये कुछ टिप्स टिकी हैं — पोषण, मेहनत, आराम, और क्या मापना है। यह एक डेटाबेस में रहेगी, जिसकी रखवाली करता है ",
  "pack.cal.life.protoSoon": "जल्द आ रहा है",
