  "pack.cal.life.recSince": "{year} से",
  "pack.cal.life.tip.weight.title": "पतला रहना एकमात्र साबित हुई बात है",
  "pack.cal.life.tip.weight.body": "कुत्ते के लिए जो भी किया जा सकता है, उनमें से उम्र पर सबसे पक्के सबूत वाली एक बात है: उसे वज़न न बढ़ने देना। पतले कुत्ते और थोड़े मोटे कुत्ते के बीच का फ़र्क़ सालों का है, महीनों का नहीं। बिना दबाए पसलियां महसूस होनी चाहिए।",
  "pack.cal.life.tip.move.title": "असली ज़मीन पर हलचल, ब्लॉक के चक्कर नहीं",
  "pack.cal.life.tip.move.body": "असमतल ज़मीन जोड़ों, मांसपेशियों और दिमाग़ को सक्रिय रखती है। आपकी हर दर्ज की हुई यात्रा इस ग्रिड पर एक गहरा सप्ताह बन जाती है — और गहरे सप्ताह ही वह चीज़ है जिसे आप वाकई प्रभावित कर सकते हैं।",
  "pack.cal.life.tip.food.title": "ऐसा खाना जिसे कुत्ता खाना पहचाने",
  "pack.cal.life.tip.food.body": "कच्ची सामग्री और कटोरे के बीच जितने कम चरण होंगे, रास्ते में उतनी ही कम चीज़ें गड़बड़ हो सकती हैं। किबल पाप नहीं है, लेकिन यह खुराक भी नहीं है — यह एक शॉर्टकट है।",
  "pack.cal.life.tip.chem.title": "रसायन केवल तब जब वास्तव में ज़रूरत हो",
  "pack.cal.life.tip.chem.body": "साल भर के परासाइट उपचार, सुविधा के लिए बेहोशी, और 'बस सावधानी के लिए' एंटीबायोटिक्स — ये फ़ैसले हैं, आदत नहीं। हर एक के लिए पूछें: अगर मैं यह न करूं तो क्या होगा? जहां जवाब 'कुछ नहीं' है, वहां न करें।",
  "pack.cal.life.tip.stress.title": "आराम भी हलचल जितना ही मायने रखता है",
  "pack.cal.life.tip.stress.body": "जो कुत्ता हमेशा सतर्क रहता है वह शरीर को भीतर से जलाता है। बिना रुकावट की नींद, एक अनुमानित दिन, और मेहनत के बाद शांति — ये आलस नहीं हैं — ये वे घंटे हैं जिनमें शरीर ख़ुद को ठीक करता है।",
  "pack.cal.life.tip.protocol.title": "घबराकर पशु चिकित्सक के पास भागने के बजाय एक प्रोटोकॉल",
  "pack.cal.life.tip.protocol.body": "डीवॉर्मिंग, कॉप्रोलॉजी और ब्लड टेस्ट की कैलेंडर में अपनी-अपनी विंडो होती है। जिस कुत्ते का ख़ून साल में दो बार जांचा जाता है उसका इलाज नहीं हो रहा — उसे आगे रखा जा रहा है।",
  "pack.cal.life.tip.joints.title": "जोड़ों का इलाज दर्द शुरू होने से पहले करें",
  "pack.cal.life.tip.joints.body": "आपका कुत्ता अब सीनियर उम्र में है। जोड़ों का कोर्स कैलेंडर में नवंबर से शुरू होता है — इसलिए नहीं कि वह लंगड़ा रहा है, बल्कि इसलिए कि उसे कभी लंगड़ाना न पड़े।",
