  "pack.hero.popStatusEyebrow": "स्थिति",
  "pack.hero.popPawtner1": "Pawtner झुंड में आपका स्थान है — आप उस कुत्ते के साथी हैं जिसके लिए आपने HEROGLYPH बनाया। बिना heroglyph, कोई डॉगिप्तवासी नहीं।",
