  "pack.msg.modMenuExplain": "ब्लॉक करना तुरंत होता है और दोनों तरफ़ से काम करता है — आप दोनों में से कोई भी दूसरे को नहीं लिख सकता। रिपोर्ट करना किसी को सज़ा नहीं देता: यह थ्रेड झुंड के रखवालों के पास चुपचाप चला जाता है, जो तभी कदम उठाते हैं जब कुछ सुलझाने की ज़रूरत हो।",
