  "pack.nature.intro.body": "बाईस सवाल और एक चेकलिस्ट। आप जानेंगे कि आपका कुत्ता किससे बना है, वह आपके परिवार के लिए क्या काम करता है, और उसका संतुलन अभी किस तरफ़ झुका हुआ है।",
  "pack.nature.intro.axis1": "संरचना",
