  "pack.nature.balance.body": "आपके कुत्ते की संरचना जीवन भर के लिए तय है, पर यह असंतुलित हो सकती है। जो भी लागू हो उसे चुनें — जितना चाहें या बिल्कुल भी नहीं।",
