  "pack.network.ads.body": "पेड विज्ञापन नए कुत्ता प्रेमियों को खोजने का एक बहुत अक्षम तरीक़ा है — और हमारा पैसा बड़ी कंपनियों पर फ़ेंकने का एक तरीक़ा है। आंदोलन के सक्रिय सदस्यों को सीधे इनाम देना कहीं बेहतर काम करता है। एक पेंच है: <strong style=\"font-weight:600\">यह सचमुच तभी काम करता है जब आप बाहर जाकर अपने आसपास के लोगों को हमारे बारे में बताते हैं</strong> :)",
