  "pack.network.capHintRow": "सीमा 1:1 — गिफ़्ट उतना बराबर करता है जितना आप जी चुके हैं",
  "pack.network.capped.none": "इस ट्रांसफ़र से कोई समर्पण नहीं — आपके गिफ़्ट पहले से ही आपके जीए हुए सब कुछ के बराबर हैं। BONES फिर भी चले जाएंगे। <i>पैसा सालों को दोगुना करता है, उन्हें कभी बदलता नहीं।</i>",
  "pack.network.capped.room": "<b style=\"color:#2a1608\">{room}</b> पर सीमित — एक गिफ़्ट सिर्फ़ उतना बराबर कर सकता है जितना आप जी चुके हैं (अभी तक {lived} समर्पण)। BONES फिर भी चले जाएंगे; सम्मान उन दिनों का इंतज़ार करता है।",
