  "pack.network.inLine": "आपकी लाइन में",
  "pack.network.info.bones.body": "BONES DOGYPT की आंतरिक मुद्रा है — एक असली चीज़ के लिए एक मज़ेदार नाम। एक कुत्ता हड्डियों में भुगतान करता है; हम भी। आप इन्हें कुत्ता प्रेमियों को झुंड में लाकर और आंदोलन को आगे बढ़ाकर <b>कमाते</b> हैं, और DOGYPT के भीतर <b>ख़र्च</b> करते हैं: शेल्टर संग्रहों का समर्थन करके, मर्च पाकर, और बाद में अन्य डॉगिप्तवासियों को उनके बनाए के लिए भुगतान करके। <b>{n} BONES = €1.</b>",
  "pack.network.info.bones.cap": "BONES क्या हैं?",
  "pack.network.info.why.body": "इस आकार का आंदोलन ख़रीदा नहीं जा सकता — कोई बजट किसी अजनबी तक वैसे नहीं पहुंचता जैसे एक डॉगिप्तवासी किसी दोस्त तक पहुंचता है। इसलिए झुंड इनाम वहां रखता है जहां पहुंच है — आप तक। जब कोई आपके लिंक से जुड़ता है तो आपको <b>{l1} BONES</b> मिलते हैं; जब वह किसी को लाता है, तो आपको <b>{l2}</b> और मिलते हैं। जो भी डॉगिप्तवासी बात फैलाता है वह सेल्सपर्सन नहीं है — वह एक मिशनरी है, और हम इस काम का सम्मान करते हैं।",
  "pack.network.info.why.cap": "हम आपसे क्यों पूछते हैं",
  "pack.network.intro": "एक आंदोलन तभी बढ़ता है जब उसके सदस्य संदेश ले जाते हैं और नए लोगों को लाते हैं। इसलिए हम आपसे सीधे पूछते हैं: <strong style=\"color:#2a1608;font-weight:600\">अपने जाने-पहचाने कुत्ता प्रेमियों को आमंत्रित करें</strong>। यह ठीक-ठीक काम करने का तरीक़ा है।",
