  "pack.profile.wizard.step.devotion.body": "यह आपका बंधन है, दिखने योग्य बनाया गया। आवारा → पपी → … → अर्धदेव। आप स्तर नहीं ख़रीदते — आप अपने कुत्ते के लिए मौजूद रहकर उन्हें कमाते हैं।",
