  "wall.guestLine.1": "मेरे इंसान को अभी समझ नहीं आया। मैं उस पर काम कर रहा हूं।",
  "wall.guestLine.2": "मैं अंदर हूं। मेरा इंसान अभी भी दरवाज़े पर खड़ा है।",
  "wall.guestLine.3": "मेरे इंसान ने अभी तक यह विज़न नहीं देखा। मैंने देख लिया है।",
