  "about.legends.titleFilm": "प्रेम की भाषा: DOG",
  "about.legends.subFilm": "हर कोई कुत्तों से प्यार करता है — फिर भी अब तक कोई आधिकारिक वैश्विक फैन क्लब नहीं है!",
