  "onepage.apps.insp": "प्रेरणा",
  "onepage.apps.mapy": "मैप्स सौजन्य",
  "onepage.apps.claude": "AI सौजन्य",
  "onepage.apps.dogid.lede": "आपके कुत्ते की हर जानकारी एक जगह — आपके पशु-चिकित्सक और AINUBIS से व्यक्तिगत देखभाल की कुंजी।",
  "onepage.apps.dogtrip.lede": "जाँचे-परखे कुत्ता-अनुकूल रास्ते खोजें और अपने रास्ते दर्ज करें। साथ बिताए सक्रिय जीवन के लिए पॉइंट और बैज जमा करें।",
  "onepage.apps.sniffer.lede": "कुत्ता-अनुकूल मेलजोल का मंच। दुनिया घूमने के लिए साथी, टोली या हमसफ़र खोजें — एक झुंड की तरह।",
  "onepage.apps.cause.name": "समुदाय की शक्ति",
  "onepage.apps.cause.lede": "हम कुत्तों के प्रेम में DOGYPT को मिलकर बना रहे हैं — 100 % पारदर्शी। हर सदस्य सारी आय और खर्च देख सकता है।",
  "onepage.apps.ainubis.lede": "हमारा व्यक्तिगत AI मार्गदर्शक जो आपके कुत्ते को भीतर से जानता है — जाँची-परखी किताबों, लेखों और छोटे पॉडकास्ट से सीखता है।",
  "onepage.apps.head": "सदस्यता",
  "onepage.apps.sub1": "हम एक कुत्तों की दुनिया बना रहे हैं — हर कुत्ता प्रेमी के लिए एक मददगार, मनोरंजक इकोसिस्टम।",
  "onepage.apps.chips.lead": "एक ऐप, इन सबका सर्वश्रेष्ठ लेकर:",
  "onepage.apps.chips.more": "और भी बहुत कुछ…",
  "onepage.apps.chips.tail": "…कुत्ता प्रेमियों के लिए खास तौर पर बनाया गया।",
  "onepage.apps.lang.a": "Heroglyph एक सार्वभौमिक भाषा है।",
  "onepage.apps.lang.b": "ऐप इनमें से 18 बोलता है।",
  "onepage.apps.more": "विवरण",
  "onepage.apps.tap": "मुझे टैप करें",
  "onepage.apps.prev": "पिछला",
  "onepage.apps.next": "अगला",
  "onepage.fin.photoAlt": "Matej और Hektor",
  "onepage.fin.forMe": "(मेरे लिए)",
  "onepage.fin.p1": "नमस्ते, मैं Matthew हूँ। नौ साल पहले मेरी ज़िंदगी बदल गई — एक शेल्टर के कुत्ते की वजह से। कुत्ते के प्यार की ताक़त महसूस करने के बाद मुझे एक सपना दिखा कि कुत्तों का एहसान कैसे चुकाया जाए — सिर्फ़ मेरे कुत्ते का नहीं, बल्कि दुनिया के हर कुत्ते का।",
  "onepage.fin.p2": "तब यह सिर्फ़ एक विचार था — AI की बदौलत अब मैं इसे आख़िरकार बना सकता हूँ। जब भी मौसम अच्छा होता है, मैं Hekthor के साथ सैर पर होता हूँ, और जब वह आराम करता है, मैं DOGYPT पर जी-जान से काम करता हूँ। मुझे इस मिशन का जुनून है — मैं इसके लिए सब कुछ कुर्बान करता हूँ और अपना हर आख़िरी यूरो इसमें लगाता हूँ। मेरे क़रीबी कहते हैं कि मैं सपने देखने वाला हूँ जो बहुत ज़्यादा जोखिम लेता है — लेकिन मुझे यक़ीन है कि यह विचार लड़ने लायक़ है, और यह बस समय की बात है।",
  "onepage.fin.p3": "कृपया हमें इंतज़ार न करवाएँ — आज ही हमसे जुड़ें, ताकि मुझे प्लान B (OnlyFans) पर न जाना पड़े।",
  "onepage.fin.aboutMore": "मेरे बारे में और जानें",
  "onepage.fin.liveHead": "लाइव स्थिति",
  "onepage.fin.aiLine": "यह प्रोजेक्ट <b>कुत्तों</b> के प्रति प्रेम से — और <b>AI</b> के साथ बनाया जा रहा है।",
