  "onepage.hbook.0.title": "एक समय की बात है…",
  "onepage.hbook.0.glyph": "Hekthor का heroglyph",
  "onepage.hbook.0.sub": "Hekthor · कुत्ता #1",
  "onepage.hbook.0.cap": "आईना",
  "onepage.hbook.1.ini": "अ",
  "onepage.hbook.1.lead": "नचाहा जन्मा। एक डिब्बे में फेंक दिया गया, जहाँ वह अपने भाइयों के साथ मौत का इंतज़ार करता रहा।",
  "onepage.hbook.1.txt": "आठ नन्ही जानें एक शेल्टर में पहुँचीं। सात को घर मिल गया। सिर्फ़ एक पीछे रह गया — सबसे बड़ा, सबसे बड़े मिज़ाज वाला। एक साल बाद, निरे संयोग से, उसकी मुलाक़ात Matej से हुई, जिसने कभी कुत्ता पालने की सोची ही नहीं थी। एक चिंगारी भड़की, और जून 2017 से वे साथ-साथ ज़िंदगी की राह पर चल रहे हैं।",
  "onepage.hbook.1.cap": "डिब्बे में आठ",
  "onepage.hbook.2.ini": "उ",
  "onepage.hbook.2.lead": "सने एक इंसान की जान बचाई। वह उसके जीवन के सबसे कठिन मौसम में आया।",
  "onepage.hbook.2.txt": "सबसे अँधेरे दिनों में वह Matej का लंगर था — उसने उसे अँधेरे ख़यालों से, घर से बाहर निकालकर प्रकृति में पहुँचाया। पहले आसपास की गलियाँ, फिर जंगल और पहाड़। उन्होंने पूरा स्लोवाकिया (820 किमी) पार किया और पूरे यूरोप में रोड ट्रिप किए। रोमांच और सड़क पर आज़ाद जीवन ने उन्हें बाँध दिया।",
  "onepage.hbook.2.cap": "दफ़्तर से दुनिया में",
  "onepage.hbook.3.ini": "उ",
  "onepage.hbook.3.lead": "सकी निर्मल आत्मा ने कुत्ता प्रेमियों के लिए एक वैश्विक आंदोलन का सपना दिया।",
  "onepage.hbook.3.txt": "कुत्ते के साथ जीवन किसी के भी जीवन का सबसे सुंदर अध्याय है। कुत्ते वाले लोग एक अलग तरह के लोग होते हैं — वे बार-बार वही ख़ास समस्याएँ सुलझाते रहते हैं, और कुत्तों के प्रति प्रेम उन्हें बाँधता है। क्या हो अगर यह कहानी कुछ उपयोगी बन जाए?",
  "onepage.hbook.3.cap": "एक सपने का जन्म",
  "onepage.hbook.4.ini": "द",
  "onepage.hbook.4.lead": "स खूबसूरत साल उसके पीछे हैं, और कम से कम दस आगे हैं!",
  "onepage.hbook.4.txt": "Hekthor ने Matej को कुत्तों के बारे में सब कुछ सीखने की प्रेरणा दी — मनोविज्ञान, प्रशिक्षण, खेल और सबसे बढ़कर दीर्घायु। यह सारा ज्ञान DOGYPT में सबके काम आएगा: एक और दिखावटी सोशल नेटवर्क नहीं, बल्कि सार्थक सामग्री वाला नेटवर्क। और यह सब एक “साधारण” शेल्टर के कुत्ते की वजह से।",
  "onepage.hbook.4.cap": "संस्थापक #1",
  "onepage.hbook.5.ini": "आ",
  "onepage.hbook.5.lead": "ज वह स्लोवाकिया में रहता है — जंगलों में, पहाड़ों में और झीलों के किनारे।",
  "onepage.hbook.5.txt": "पानी से चीज़ें लाना उसका सबसे बड़ा प्यार है। वह बेहतरीन सेहत में है, समझदार, विनम्र और कोई भी जैसा साथी चाह सकता है, उससे बढ़कर। जब हम बाहर नहीं होते, तो वह घर पर दो बिल्लों, Gary और Yby, की रखवाली करता है, जिन्हें उसने सड़क से बचाया था।",
  "onepage.hbook.5.cap": "घर का रखवाला",
